n        },\n        dateFormat(date) {\n            const arrStr = date.split(' ')\n            const dateFormat = arrStr[0] + '<br>' + arrStr[1]\n            return dateFormat\n        },\n        phoneFormat(phone) {\n            if (!phone) return\n            return phone.toString().replace(/(\\d{1})(\\d{3})(\\d{3})(\\d{4})/, '+7 ($2) $3-$4')\n        },\n        sumFormat(sum) {\n            if (!sum) return\n            const sumStr = sum.toString()\n            return sumStr.replace(/(\\d{1,3}(?=(?:\\d\\d\\d)+(?!\\d)))/g, \"$1\" + ' ')\n        }\n    },\n    computed: {\n        stateProjectId() {\n            return this.$store.getters['journalAll/stateProjectId']\n        },\n        stateLeads () {\n            return this.$store.getters.stateLeads\n        },\n        stateProjectJour () {\n            return this.$store.getters.stateProjectJour\n        }\n    }\n}\n</script>\n\n<style scoped>\n.dropdown-toggle::after {\n    display: none;\n}\n.dropdown-menu::before {\n    color: #e91e63;\n}\nth {\n    position: relative;\n}\nth, td {\n    border-width: 1px;\n}\n.journal {\n    height: calc(100vh - 160px);\n}\n.journal__col-resize {\n    position: absolute;\n    z-index: 2;\n    width: 8px;\n    height: 100%;\n    top: 0;\n    right: -4px;\n    cursor: col-resize;\n}\n.table {\n    position: relative;\n}\n.journal__thead {\n    position: sticky;\n    left: 0;\n    top: 0;\n    width: 100%;\n    z-index: 200;\n    background-color: #FCFCFE;\n}\n.dark-version .journal__thead {\n    background-color: #202940;\n}\n.journal__thead::after {\n    content: '';\n    position: absolute;\n    width: 100%;\n    height: 1px;\n    left: 0;\n    bottom: 0;\n    background-color: #797F8D;\n}\n.journal__box {\n    height: 100%;\n}\n.journal__card {\n    height: 100%;\n    overflow: hidden;\n}\n.journal__wrap {\n    height: 100%;\n}\n\n.journal__sort__label {\n    position: relative;\n    cursor: pointer;\n    display: block;\n    text-align: left;\n    transition: 0.3s